package main

// Regression test: a voucher send must be rejected when it does not originate
// from transfer.Transfer. OnSendPacket is reachable directly through the public
// core.SendPacket router, so the direct-user-call guard in transfer.Transfer is
// not sufficient on its own — OnSendPacket must also require that voucher (and
// GRC20) sends were initiated through transfer.Transfer, mirroring the existing
// native-branch pendingNativeEscrow check.
//
// Here core.SendPacket is invoked directly with a voucher payload whose Sender
// equals OriginCaller; the immediate caller is a realm (this main), not a user.
// Until the OnSendPacket-level guard lands this test FAILS because the send
// succeeds and burns the owner's voucher.

import (
	"encoding/hex"
	"time"

	tmtesting "gno.land/p/aib/ibc/lightclient/tendermint/testing"
	"gno.land/p/aib/ibc/types"

	"gno.land/p/aib/ics23"
	"gno.land/r/aib/ibc/apps/transfer"
	"gno.land/r/aib/ibc/core"
)

func main(cur realm) {
	var (
		chainID        = "chain-id-2"
		trustedHeight  = types.NewHeight(2, 2)
		clientState    = tmtesting.NewClientState(chainID, trustedHeight)
		apphash, _     = hex.DecodeString("0eadf50c7992d8e1366b8ea63ab7d1346de4762c3d449764ef7dc404ba48381f")
		trustedValset  = tmtesting.GenValset()
		consensusState = tmtesting.GenConsensusState(time.Now(), apphash, trustedValset.Hash())
		counterpartyID = "07-tendermint-42"
	)
	clientID := core.CreateClient(cross(cur), clientState, consensusState)
	core.RegisterCounterparty(cross(cur), clientID, [][]byte{[]byte("iavlStoreKey"), []byte("prefix2")}, counterpartyID)

	// The voucher owner is the signing EOA (OriginCaller). RecvPacket mints 100
	// vouchers to it so the balance is non-zero.
	owner := cur.Previous().Address()
	recvPacket(cur, clientID, counterpartyID, trustedHeight, owner)

	// Build a voucher send packet and submit it straight to the core router,
	// bypassing transfer.Transfer and its guard. The guard must instead reject
	// this at the OnSendPacket layer.
	data := transfer.NewFungibleTokenPacketData("transfer/"+clientID+"/uphoton", "100", owner.String(), "atone1user", "")
	msg := types.MsgSendPacket{
		SourceClient: clientID,
		Payloads: []types.Payload{{
			SourcePort:      transfer.PortID,
			DestinationPort: transfer.PortID,
			Encoding:        transfer.EncodingProtobuf,
			Value:           data.ProtoMarshal(),
			Version:         transfer.V1,
		}},
		TimeoutTimestamp: uint64(time.Now().Add(time.Hour).Unix()),
	}
	core.SendPacket(cross(cur), msg)
}

func recvPacket(cur realm, clientID, counterpartyID string, trustedHeight types.Height, receiver address) {
	payload := transfer.NewFungibleTokenPacketData("uphoton", "100", "atone1user", receiver.String(), "")
	payloadBz := payload.ProtoMarshal()

	specs := ics23.IavlSpec()
	// NOTE proof generated by:
	// go run -C ./cmd/gen-proof . 'prefix2' '07-tendermint-42' 'packet' '{"sequence":1,"source_client":"07-tendermint-42","destination_client":"07-tendermint-1","timeout_timestamp":1234571490,"payloads":[{"source_port":"transfer","destination_port":"transfer","encoding":"application/x-protobuf", "value":"Cgd1cGhvdG9uEgMxMDAaCmF0b25lMXVzZXIiKGcxd3ltdTQ3ZHJocjBrdXEyMDk4bTc5Mmx5dGd0ajJueXg3N3lyc20=","version":"ics20-1"}]}'
	proof := []ics23.CommitmentProof{

		// iavl proof
		ics23.CommitmentProof_Exist{
