	testing.SetRealm(testing.NewUserRealm(caller))
	transfer.Transfer(cross(cur), clientID, "atone1user", denom, 100, uint64(time.Now().Add(time.Hour).Unix()), "")

	println("----------- balance after Transfer:", grc20test.BalanceOf(caller))
}

